SHAPE=np.array([64,128,128])
def neighbors(pos):
    lo=np.floor(pos).astype(int);f=pos-lo
    for bits in itertools.product([0,1],repeat=3):
        b=np.asarray(bits);yield lo+b,float(np.prod(np.where(b,f,1-f)))
